q=maker('invariant-extremal',['invariants','pigeonhole partitions','attainable bounds'])
def reachable(n):
 seen={0};todo=[0]
 while todo:
  s=todo.pop()
  for i in range(n-1):
   t=s^(3<<i)
   if t not in seen:seen.add(t);todo.append(t)
 return len(seen)
def tournament_max():
 pairs=list(combinations(range(6),2));best=0
 for mask in range(1<<15):
  wins=[0]*6
  for i,(a,b) in enumerate(pairs):wins[b if mask>>i&1 else a]+=1
  best=max(best,sum(w>=4 for w in wins))
 return best
def difference_witness():
 a=list(range(1,11))
 for x,y in [(9,8),(7,6),(5,4),(3,2),(1,1),(1,1),(1,0),(1,0),(10,1)]:
  a.remove(x);a.remove(y);a.append(abs(x-y))
 return a[0]
def ramsey_three():
 for n in range(3,7):
  edges=list(combinations(range(n),2))
  triples=[sum(1<<edges.index(e) for e in combinations(t,2)) for t in combinations(range(n),3)]
  if all(any((mask&t)==0 or (mask&t)==t for t in triples) for mask in range(1<<len(edges))):return n
