q(1,r'What is the least number of distinct integers that must be chosen from {1,...,20} to guarantee two with sum 21?',11,[(10,'Give the largest size of a set avoiding the pair.'),(12,'Overestimate the pigeonhole threshold.'),(20,'Assume every number must be selected.'),(2,'Confuse a possible pair with a guaranteed pair.')],[r'Partition the set into ten pairs (1,20),(2,19),...,(10,11), each summing to 21.',r'Eleven selections force two from one pair.',r'Ten are insufficient: {1,...,10} contains no such pair. The least threshold is eleven.'],['Group numbers into complementary pairs.','Prove both a guarantee and a one-smaller counterexample.'],'Establish a sharp pigeonhole threshold.',lambda:len({min(x,21-x) for x in range(1,21)})+1,'Ten-pair partition and explicit size-ten avoiding set.',2),
q(2,r'What is the least number of distinct integers chosen from {1,...,30} that guarantees one selected integer divides another?',16,[(15,'Report the largest avoiding set rather than the forcing threshold.'),(11,'Group by ordinary remainders rather than divisibility chains.'),(30,'Assume all integers are needed.'),(8,'Use too few groups based only on powers of two.')],[r'Write every integer uniquely as an odd number times a power of two.',r'The fifteen possible odd parts form fifteen chains in which the smaller number divides the larger. Sixteen selections force two from one chain.',r'The fifteen numbers 16 through 30 contain no divisibility pair, since doubling any exceeds 30. Thus sixteen is least.'],['Remove all factors of two from each selected integer.','Numbers with the same odd part form a divisibility chain.'],'Invent a pigeonhole partition adapted to divisibility.',lambda:len({n//(n&-n) for n in range(1,31)})+1,'Unique odd-part chains and the explicit antichain 16 through 30.'),
q(3,r'Two diagonally opposite corner squares are removed from an 8×8 chessboard. How many tilings of the remainder by 1×2 dominoes are possible?',0,[(1,'Assume area divisibility guarantees a tiling.'),(31,'Report the number of dominoes rather than tilings.'),(2,'Assume one tiling for each orientation.'),(62,'Count remaining squares instead of tilings.')],[r'Color the board as a checkerboard. Every domino covers one square of each color.',r'Diagonally opposite corners have the same color, so the remaining board has thirty of one color and thirty-two of the other.',r'The unequal color counts make every domino tiling impossible. The answer is zero.'],['Find a quantity every domino contributes equally.' ,'Compare that quantity after the two removals.'],'Use a coloring invariant to prove impossibility.',lambda:int(sum((x+y)%2==0 for x in range(8) for y in range(8) if (x,y) not in [(0,0),(7,7)])==31),'Independent remaining-color count; the domino invariant proves nonexistence.'),
q(4,r'Start with 1,2,3,4,5. Repeatedly replace any two numbers a,b by a+b+ab until one remains. What is that final number?',719,[(15,'Assume the sum is invariant.'),(120,'Assume the unshifted product is invariant.'),(720,'Forget to undo the final shift.'),(119,'Use the product of the original numbers and then subtract one.')],[r'The replacement satisfies (a+b+ab)+1=(a+1)(b+1).',r'Thus the product of one more than every current number is invariant, initially 2·3·4·5·6=720.',r'When only N remains, N+1=720, so N=719 regardless of the choices.'],['Add one to the replacement expression and factor it.','Look for a product preserved when two entries merge.'],'Discover a shifted-product invariant.',lambda:(lambda a,b:(a+b+a*b))( (1+2+1*2)+(3+4+3*4)+((1+2+1*2)*(3+4+3*4)),5),'Independent explicit merge order.'),
q(5,r'Three piles contain 10,11,12 stones. A move adds one stone to each of two piles and removes two from the third, provided no pile becomes negative. How many equal-pile configurations can be reached?',0,[(1,'Use total-sum preservation as if it were sufficient.'),(3,'Choose which pile reaches the average first.'),(11,'Report the target size of each pile.'),(33,'Report the total number of stones.')],[r'The total remains 33, so the only equal-pile candidate is (11,11,11).',r'Modulo three, every coordinate increases by one on every move, since -2≡1. Therefore pairwise differences modulo three are invariant.',r'The initial differences are not all zero modulo three, while the target differences are. The target is unreachable.'],['The sum identifies a candidate but may not establish reachability.','Compare pairwise differences modulo three under one move.'],'Combine two invariants to rule out a feasible-looking target.',lambda:int(all((a-b)%3==0 for a,b in combinations([10,11,12],2))),'Direct transition residue check; invariant separates start and target.'),
q(6,r'Six players each play one game against every other player, with no draws. What is the largest possible number of players with at least four wins?',3,[(4,'Ignore the total number of wins.'),(2,'Find a bound but miss a cyclic equality construction.'),(5,'Count potential strong players without accounting for their mutual games.'),(6,'Allow every player to win each mutual game.')],[r'There are C(6,2)=15 games and therefore fifteen wins. Four players with four wins would need sixteen, so at most three qualify.',r'Take three players who each beat the other three. Among the strong trio, arrange a cyclic win pattern so each wins one more.',r'All three then have four wins, proving the maximum is three.'],['Every game contributes exactly one win to the total.','After obtaining a bound, construct a tournament that attains it.'],'Combine a global sum bound with a local cyclic construction.',tournament_max),
